1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Soft-match duplicate detection for create-owner. Runs after the hard-duplicate check
9	 * ({@link RejectDuplicateOwner}), so the owner being created has a telephone not already in use.
10	 * If it nonetheless shares an existing owner's lastName (case-insensitively) and postcode while
11	 * using a different telephone, it is still created but flagged: {@code possibleDuplicate} is set
12	 * true and {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several
13	 * match). Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is null.
14	 *
15	 * <p>Runs before the owner is saved, so {@link OwnerRepository#findAll()} sees only owners that
16	 * existed before this create.
17	 */
18	public class DetectPossibleDuplicate {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String lastName = owner.getLastName();
22	        String postcode = owner.getPostcode();
23	        String telephone = owner.getTelephone();
24	        Owner match = null;
25	        if (lastName != null && postcode != null) {
26	            for (Owner existing : ownerRepository.findAll()) {
27	                if (lastName.equalsIgnoreCase(existing.getLastName())
28	                        && postcode.equals(existing.getPostcode())
29	                        && (telephone == null || !telephone.equals(existing.getTelephone()))) {
30	                    if (match == null || existing.getId() < match.getId()) {
31	                        match = existing;
32	                    }
33	                }
34	            }
35	        }
36	        if (match != null) {
37	            owner.setPossibleDuplicate(true);
38	            owner.setPossibleDuplicateOf(match.getId());
39	        } else {
40	            owner.setPossibleDuplicate(false);
41	            owner.setPossibleDuplicateOf(null);
42	        }
43	    }
44	}
45

